def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_def_total = 0
    for _, o in history:
        if o == 'D':
            opp_def_total += 1

    last_my, last_opp = history[-1]

    if n >= 90:
        if n == 99:
            return 'D'

        opp_def_before = sum(1 for i in range(90) if history[i][1] == 'D')
        last_opp_before = history[89][1]
        probe_condition = (opp_def_before <= 1 and last_opp_before == 'C')

        if n == 90:
            if probe_condition:
                return 'D'
        if n == 91:
            if probe_condition and history[90][0] == 'D':
                return 'C'
        if n >= 92:
            if probe_condition and history[90][0] == 'D' and history[91][0] == 'C':
                if opp_def_total <= 1 and last_opp == 'C':
                    return 'D'

    if opp_def_total <= 1:
        return 'C'

    if last_my == 'D' and last_opp == 'D':
        if opp_def_total < n * 0.5:
            return 'C'
        else:
            return 'D'

    if last_opp == 'D':
        return 'D'
    else:
        return 'C'
